do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'US';
  if n <> 51 then raise exception 'US: expected 51 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('rest_0045', 'Eleven Madison Park'), ('rest_0053', 'Jungsik New York'), ('rest_0059', 'Le Bernardin'), ('rest_0080', 'Per Se'), ('rest_0102', 'Sushi Sho'), ('rest_0302', 'Atomix'), ('rest_0735', 'The French Laundry'), ('rest_0736', 'SingleThread'), ('rest_0737', 'Benu'), ('rest_0738', 'Atelier Crenn'), ('rest_0739', 'Quince'), ('rest_0740', 'Californios'), ('rest_0741', 'Enclos'), ('rest_0742', 'Addison'), ('rest_0743', 'Providence'), ('rest_0744', 'Somni'), ('rest_0745', 'Smyth'), ('rest_0746', 'Saison'), ('rest_0747', 'Acquerello'), ('rest_0748', 'Birdsong'), ('rest_0749', 'Lazy Bear'), ('rest_0750', 'Sons & Daughters'), ('rest_0751', 'Kiln'), ('rest_0752', 'Commis'), ('rest_0753', 'Aubergine'), ('rest_0754', 'Vespertine'), ('rest_0755', 'Harbor House Inn'), ('rest_0756', 'Hayato'), ('rest_0757', 'Kato'), ('rest_0758', 'Mélisse'), ('rest_0759', 'Aquavit'), ('rest_0760', 'Aska'), ('rest_0761', 'Atera'), ('rest_0762', 'Blue Hill at Stone Barns'), ('rest_0763', 'César'), ('rest_0764', 'Chef''s Table at Brooklyn Fare'), ('rest_0765', 'Gabriel Kreuther'), ('rest_0766', 'Jean-Georges'), ('rest_0767', 'Joo Ok'), ('rest_0768', 'odo'), ('rest_0769', 'Saga'), ('rest_0770', 'Sushi Noz'), ('rest_0771', 'The Modern'), ('rest_0772', 'Alinea'), ('rest_0773', 'Ever'), ('rest_0774', 'Kasama'), ('rest_0775', 'Oriole'), ('rest_0776', 'Jônt'), ('rest_0777', 'minibar by José Andrés'), ('rest_0778', 'The Inn at Little Washington'), ('rest_0779', 'L''Atelier de Joël Robuchon')) e(code, name)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = 'US');
  if n <> 0 then raise exception 'US: % exported restaurant codes no longer carry their exported name', n; end if;
  select count(*) into n from public.hotels where country_code = 'US';
  if n <> 11 then raise exception 'US: expected 11 hotels (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('hotel_771', 'Aman New York'), ('hotel_772', 'Amangiri'), ('hotel_773', 'Equinox Hotel New York'), ('hotel_774', 'Four Seasons at The Surf Club'), ('hotel_775', 'Hotel Bel-Air'), ('hotel_776', 'San Ysidro Ranch'), ('hotel_777', 'The Beverly Hills Hotel'), ('hotel_778', 'The Carlyle'), ('hotel_779', 'The Fifth Avenue Hotel'), ('hotel_780', 'The Greenwich Hotel'), ('hotel_781', 'The Mark')) e(code, name)
   where not exists (select 1 from public.hotels h where h.hotel_code = e.code and h.name = e.name and h.country_code = 'US');
  if n <> 0 then raise exception 'US: % exported hotel codes no longer carry their exported name', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 3001 and 3228) then
    raise exception 'restaurant codes rest_3001..rest_3228 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 1501 and 1849) then
    raise exception 'hotel codes hotel_1501..hotel_1849 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

-- US 1. MICHELIN Key hotels missing from `hotels` (each with its current 2026 Key row, step 1c)
create temp table _new_hotels_us (code text, name text, keys smallint, city text, city_region text, address text, lon float8, lat float8,
                               michelin_url text, website_url text, phone text) on commit drop;
do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_us x
   where (select count(*) from public.cities c where c.country_code = 'US' and c.name = x.city and c.region is not distinct from x.city_region) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one US row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_us x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
select x.code, x.name, x.keys, (select c.id from public.cities c where c.country_code = 'US' and c.name = x.city and c.region is not distinct from x.city_region), 'US',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_us x;

-- US 1b. Key changes on existing hotels (2026 Keys): close the current Key row; 1c opens 2026
create temp table _kchg_us (code text primary key, keys smallint, was smallint) on commit drop;
update public.award_history a set is_current = false from public.hotels h, _kchg_us k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys' and a.is_current;
update public.hotels h set michelin_keys = k.keys, updated_at = now() from _kchg_us k
 where h.hotel_code = k.code and h.michelin_keys is not distinct from k.was;

