-- US 1d. existing US hotels, fill-only (never overwrites)
create temp table _hfill_us (code text primary key, phone text, website_url text, michelin_url text) on commit drop;
update public.hotels h set phone = f.phone, updated_at = now() from _hfill_us f where h.hotel_code = f.code and f.phone is not null and h.phone is null;
update public.hotels h set website_url = f.website_url, updated_at = now() from _hfill_us f where h.hotel_code = f.code and f.website_url is not null and h.website_url is null;
update public.hotels h set michelin_url = f.michelin_url, updated_at = now() from _hfill_us f where h.hotel_code = f.code and f.michelin_url is not null and h.michelin_url is null
   and not exists (select 1 from public.hotels o where o.michelin_url = f.michelin_url);

-- US 2a. relabel verified launch rows 2026 -> 2025 (values unchanged; each agrees with MICHELIN's live
--     page, whose current edition for these guides is 2025: Northeast Cities, announced 18 Nov 2025)
do $$
begin
  if exists (select 1 from public.award_history ah join public.restaurants r on r.id = ah.entity_id
              where ah.entity_type = 'restaurant' and ah.award_type = 'michelin_stars' and ah.guide_year = 2025
                and r.restaurant_code = any(array['rest_0045', 'rest_0053', 'rest_0059', 'rest_0080', 'rest_0302', 'rest_0745', 'rest_0759', 'rest_0760', 'rest_0761', 'rest_0762', 'rest_0763', 'rest_0764', 'rest_0765', 'rest_0766', 'rest_0767', 'rest_0768', 'rest_0769', 'rest_0770', 'rest_0771', 'rest_0772', 'rest_0773', 'rest_0774', 'rest_0775', 'rest_0776', 'rest_0777', 'rest_0778'])) then
    raise exception 'US: 2025 rows already exist for relabel candidates -- this file has run?';
  end if;
end $$;
update public.award_history ah set guide_year = 2025
  from public.restaurants r
 where r.id = ah.entity_id and ah.entity_type = 'restaurant' and ah.award_type = 'michelin_stars'
   and ah.guide_year = 2026 and ah.is_current and ah.announced_on is null
   and r.restaurant_code = any(array['rest_0045', 'rest_0053', 'rest_0059', 'rest_0080', 'rest_0302', 'rest_0745', 'rest_0759', 'rest_0760', 'rest_0761', 'rest_0762', 'rest_0763', 'rest_0764', 'rest_0765', 'rest_0766', 'rest_0767', 'rest_0768', 'rest_0769', 'rest_0770', 'rest_0771', 'rest_0772', 'rest_0773', 'rest_0774', 'rest_0775', 'rest_0776', 'rest_0777', 'rest_0778']);

-- US 2a'. launch rows 2026 that predate any 2026 edition, where a 2025 row already exists
--     (relabelling would collide): drop the launch row, make 2025 current (values agree with
--     MICHELIN's live 2025 page; product owner, 2026-10-30, QA-301). The delete comes first:
--     only one current row per entity and award type is allowed.
create temp table _drop26_us (code text primary key, value smallint) on commit drop;
do $$
declare n int;
begin
  select count(*) into n from _drop26_us d join public.restaurants r on r.restaurant_code = d.code
    join public.award_history ah on ah.entity_type = 'restaurant' and ah.entity_id = r.id and ah.award_type = 'michelin_stars'
   where (ah.guide_year = 2026 and ah.is_current and ah.announced_on is null and ah.award_value = d.value)
      or (ah.guide_year = 2025 and not ah.is_current and ah.award_value = d.value);
  if n <> 2 then raise exception 'US: launch-row fix expected 2 rows (2026 current + 2025 not current), found %', n; end if;
end $$;
delete from public.award_history ah using public.restaurants r, _drop26_us d
 where r.restaurant_code = d.code and ah.entity_id = r.id and ah.entity_type = 'restaurant' and ah.award_type = 'michelin_stars'
   and ah.guide_year = 2026 and ah.is_current and ah.announced_on is null and ah.award_value = d.value;
update public.award_history ah set is_current = true from public.restaurants r, _drop26_us d
 where r.restaurant_code = d.code and ah.entity_id = r.id and ah.entity_type = 'restaurant' and ah.award_type = 'michelin_stars'
   and ah.guide_year = 2025 and not ah.is_current and ah.award_value = d.value;

-- US 4. starred restaurants missing from the catalogue (Place ID NULL: no Places API in this pass);
--    each award row takes its own guide's year and announcement date
create temp table _new_us (code text, name text, stars smallint, city text, city_region text, address text, lon float8, lat float8,
                        michelin_url text, website_url text, phone text, property_name text, place_id text,
                        guide_year smallint, announced_on date) on commit drop;
do $$
declare bad text;
begin
  select string_agg(x.code, ', ') into bad from _new_us x join public.restaurants r on r.restaurant_code = x.code;
  if bad is not null then raise exception 'codes no longer free: %', bad; end if;
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_us x
   where (select count(*) from public.cities c where c.country_code = 'US' and c.name = x.city and c.region is not distinct from x.city_region) <> 1;
  if bad is not null then raise exception 'city does not resolve to exactly one US row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_us x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'already present (michelin_url): %', bad; end if;
end $$;
                                address, location, michelin_url, website_url, phone, property_name, google_place_id)
select x.code, x.name, x.stars, 'michelin_star', (select c.id from public.cities c where c.country_code = 'US' and c.name = x.city and c.region is not distinct from x.city_region), 'US',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone, x.property_name, x.place_id
  from _new_us x;
select 'restaurant', r.id, x.guide_year, 'michelin_stars', x.stars, true, x.announced_on
  from _new_us x join public.restaurants r on r.restaurant_code = x.code;

-- US 5. existing restaurants, fill-only (never overwrites)
create temp table _fill_us (code text primary key, phone text, website_url text, property_name text, michelin_url text) on commit drop;
update public.restaurants r set phone = f.phone, updated_at = now() from _fill_us f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_us f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set michelin_url = f.michelin_url, updated_at = now() from _fill_us f where r.restaurant_code = f.code and f.michelin_url is not null and r.michelin_url is null
   and not exists (select 1 from public.restaurants o where o.michelin_url = f.michelin_url);
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_us f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

-- US 6. links to hotels in `hotels`; the host of 2 existing restaurant(s) with a property_name is now in
--    `hotels`, so the link replaces the free-text name (hotel scope rule 3; guarded on the stored value)
create temp table _pclear_us (code text primary key, was text) on commit drop;
update public.restaurants r set property_name = NULL, updated_at = now() from _pclear_us p
 where r.restaurant_code = p.code and r.property_name = p.was;
create temp table _links_us (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
do $$
declare n int;
begin
  select count(*) into n from _links_us l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_us l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- US post-conditions: MICHELIN's live US listings (every guide) and the 2026 US Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'US' and michelin_stars = 3;
  if n <> 16 then raise exception 'US: expected 16 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'US' and michelin_stars = 2;
  if n <> 40 then raise exception 'US: expected 40 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'US' and michelin_stars = 1;
  if n <> 223 then raise exception 'US: expected 223 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'US' and ah.guide_year = 2025 and ah.award_value = 1;
  if n <> 87 then raise exception 'US: expected 87 current 2025 rows of 1 star(s), found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'US' and ah.guide_year = 2025 and ah.award_value = 2;
  if n <> 22 then raise exception 'US: expected 22 current 2025 rows of 2 star(s), found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'US' and ah.guide_year = 2025 and ah.award_value = 3;
  if n <> 6 then raise exception 'US: expected 6 current 2025 rows of 3 star(s), found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'US' and ah.guide_year = 2026 and ah.award_value = 1;
  if n <> 136 then raise exception 'US: expected 136 current 2026 rows of 1 star(s), found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'US' and ah.guide_year = 2026 and ah.award_value = 2;
  if n <> 18 then raise exception 'US: expected 18 current 2026 rows of 2 star(s), found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'US' and ah.guide_year = 2026 and ah.award_value = 3;
  if n <> 10 then raise exception 'US: expected 10 current 2026 rows of 3 star(s), found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'US' and r.michelin_stars is not null
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'US: % starred restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'US' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'US: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'US' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'US: % restaurants have both a hotel link and a property_name', n; end if;
  -- Keys: the 359 US Key hotels, plus the 0 hotel(s) still holding a Key MICHELIN no longer shows (left for a decision)
  select count(*) into n from public.hotels where country_code = 'US' and michelin_keys = 3;
  if n <> 15 then raise exception 'US: expected 15 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'US' and michelin_keys = 2;
  if n <> 78 then raise exception 'US: expected 78 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'US' and michelin_keys = 1;
  if n <> 266 then raise exception 'US: expected 266 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'US' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception 'US: % Key hotels without exactly one matching current Key row', n; end if;
end $$;

