  select count(*) into n from public.hotels where country_code = 'CA';
  if n <> 0 then raise exception 'CA: expected 0 hotels (export), found % -- production changed, re-check', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 3229 and 3267) then
    raise exception 'restaurant codes rest_3229..rest_3267 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 1850 and 1891) then
    raise exception 'hotel codes hotel_1850..hotel_1891 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

-- CA 1. MICHELIN Key hotels missing from `hotels` (each with its current 2026 Key row, step 1c)
create temp table _new_hotels_ca (code text, name text, keys smallint, city text, city_region text, address text, lon float8, lat float8,
                               michelin_url text, website_url text, phone text) on commit drop;
do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_ca x
   where (select count(*) from public.cities c where c.country_code = 'CA' and c.name = x.city and c.region is not distinct from x.city_region) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one CA row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_ca x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
select x.code, x.name, x.keys, (select c.id from public.cities c where c.country_code = 'CA' and c.name = x.city and c.region is not distinct from x.city_region), 'CA',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_ca x;

-- CA 1c. current 2026 Key row for every CA Key hotel that lacks one (new rows above, and existing
--     hotels the earlier imports left without one; PE_REPORT.md finding 1)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
