 where h.hotel_code = any(array['hotel_1850', 'hotel_1851', 'hotel_1852', 'hotel_1853', 'hotel_1854', 'hotel_1855', 'hotel_1856', 'hotel_1857', 'hotel_1858', 'hotel_1859', 'hotel_1860', 'hotel_1861', 'hotel_1862', 'hotel_1863', 'hotel_1864', 'hotel_1865', 'hotel_1866', 'hotel_1867', 'hotel_1868', 'hotel_1869', 'hotel_1870', 'hotel_1871', 'hotel_1872', 'hotel_1873', 'hotel_1874', 'hotel_1875', 'hotel_1876', 'hotel_1877', 'hotel_1878', 'hotel_1879', 'hotel_1880', 'hotel_1881', 'hotel_1882', 'hotel_1883', 'hotel_1884', 'hotel_1885', 'hotel_1886', 'hotel_1887', 'hotel_1888', 'hotel_1889', 'hotel_1890', 'hotel_1891'])
