   where (select count(*) from public.cities c where c.country_code = 'CA' and c.name = x.city and c.region is not distinct from x.city_region) <> 1;
  if bad is not null then raise exception 'city does not resolve to exactly one CA row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_ca x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'already present (michelin_url): %', bad; end if;
end $$;
                                address, location, michelin_url, website_url, phone, property_name, google_place_id)
select x.code, x.name, x.stars, 'michelin_star', (select c.id from public.cities c where c.country_code = 'CA' and c.name = x.city and c.region is not distinct from x.city_region), 'CA',
