-- MX 1b. Key changes on existing hotels (2026 Keys): close the current Key row; 1c opens 2026
create temp table _kchg_mx (code text primary key, keys smallint, was smallint) on commit drop;
update public.award_history a set is_current = false from public.hotels h, _kchg_mx k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys' and a.is_current;
update public.hotels h set michelin_keys = k.keys, updated_at = now() from _kchg_mx k
 where h.hotel_code = k.code and h.michelin_keys is not distinct from k.was;

