create temp table _fill_mx (code text primary key, phone text, website_url text, property_name text, michelin_url text) on commit drop;
update public.restaurants r set phone = f.phone, updated_at = now() from _fill_mx f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_mx f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set michelin_url = f.michelin_url, updated_at = now() from _fill_mx f where r.restaurant_code = f.code and f.michelin_url is not null and r.michelin_url is null
   and not exists (select 1 from public.restaurants o where o.michelin_url = f.michelin_url);
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_mx f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

-- MX 6. links to hotels in `hotels`
create temp table _links_mx (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
do $$
declare n int;
begin
  select count(*) into n from _links_mx l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_mx l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- MX post-conditions: MICHELIN's live MX listings (every guide) and the 2026 MX Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'MX' and michelin_stars = 3;
  if n <> 0 then raise exception 'MX: expected 0 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'MX' and michelin_stars = 2;
  if n <> 2 then raise exception 'MX: expected 2 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'MX' and michelin_stars = 1;
  if n <> 27 then raise exception 'MX: expected 27 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'MX' and ah.guide_year = 2026 and ah.award_value = 1;
  if n <> 27 then raise exception 'MX: expected 27 current 2026 rows of 1 star(s), found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'MX' and ah.guide_year = 2026 and ah.award_value = 2;
  if n <> 2 then raise exception 'MX: expected 2 current 2026 rows of 2 star(s), found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'MX' and r.michelin_stars is not null
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'MX: % starred restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'MX' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'MX: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'MX' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'MX: % restaurants have both a hotel link and a property_name', n; end if;
  -- Keys: the 97 MX Key hotels, plus the 0 hotel(s) still holding a Key MICHELIN no longer shows (left for a decision)
  select count(*) into n from public.hotels where country_code = 'MX' and michelin_keys = 3;
  if n <> 3 then raise exception 'MX: expected 3 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'MX' and michelin_keys = 2;
  if n <> 21 then raise exception 'MX: expected 21 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'MX' and michelin_keys = 1;
  if n <> 73 then raise exception 'MX: expected 73 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'MX' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception 'MX: % Key hotels without exactly one matching current Key row', n; end if;
end $$;

commit;
